"""Install/run only the separate reading comparison. No app code is replaced."""
from pathlib import Path
import ast,base64,hashlib,json,zlib,sys,subprocess

DATA = ''


def main():
    root=Path(__file__).resolve().parent
    package=root/'Automation' if (root/'Automation/Common_Rules').is_dir() else root
    if not (package/'Common_Rules').is_dir():raise SystemExit('Save this file in the existing invoice reader source folder.')
    files=json.loads(zlib.decompress(base64.b64decode(DATA)))
    pending=[]
    for item in files:
        relative=Path(item['path'])
        if relative.is_absolute() or '..' in relative.parts or not (relative.parts[0]=='Reading_V3' or str(relative)=='Read_Invoice_V3.py'):
            raise SystemExit('Unexpected evaluation file; nothing installed.')
        path=package/relative
        if path.exists():
            if hashlib.sha256(path.read_bytes()).hexdigest()!=item['sha256']:
                raise SystemExit('An evaluation file already exists with different contents; existing files were preserved: '+str(path))
            continue
        text=item['text']
        if relative.suffix=='.py':ast.parse(text,filename=str(relative))
        if hashlib.sha256(text.encode('utf-8')).hexdigest()!=item['sha256']:raise SystemExit('Evaluation bundle verification failed; nothing installed.')
        pending.append((path,text))
    created=[]
    try:
        for path,text in pending:
            path.parent.mkdir(parents=True,exist_ok=True)
            with path.open('x',encoding='utf-8',newline='\n') as stream:stream.write(text)
            created.append(path)
    except Exception:
        for path in created:path.unlink(missing_ok=True)
        raise
    print('Separate Reading V3 files ready. Existing reader and import button were not changed.',flush=True)
    print('Installation only: no AI requests, XML generation, or Tally imports sent.',flush=True)
    print('For review XML, run the reader environment Python with Read_Invoice_V3.py, your selected client folder, and --xml.',flush=True)
    print('AI is opt-in: --ai-provider Groq --max-ai-requests 50. Existing matching source reviews/caches are retained.')



if __name__=='__main__':main()
